actions.script:
$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not (Test-Path -LiteralPath $liteState)) { New-Item -ItemType Directory -Path $liteState -Force | Out-Null }
$policyKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection'
$stateFile = Join-Path $liteState 'prev-defender-rtp-policy.txt'
function Get-LiteProp {
    param($Object, [string]$Name)
    if ($null -eq $Object) { return $null }
    $p = $Object.PSObject.Properties[$Name]
    if ($null -eq $p) { return $null }
    $p.Value
}
$status = $null
try { $status = Get-MpComputerStatus } catch { $status = $null }
$mode = [string](Get-LiteProp $status 'AMRunningMode')
if ($null -eq $status) {
    Write-Output 'SKIPPED: Microsoft Defender status is unavailable (another antivirus is probably active) - nothing changed.'
} elseif ($mode -ne '' -and $mode -ne 'Normal') {
    Write-Output ('SKIPPED: Microsoft Defender is not the active antivirus (mode: ' + $mode + ') - nothing changed.')
} elseif ([bool](Get-LiteProp $status 'IsTamperProtected')) {
    Write-Output 'SKIPPED: Tamper Protection is ON, and it blocks (silently undoes) this change. If you really want real-time protection off: open Windows Security > Virus & threat protection > Manage settings, switch Tamper Protection off, then run Lite OS again with this tweak included.'
} else {
    $prev = '<nokey>'
    if (Test-Path -LiteralPath $policyKey) {
        $v = (Get-Item -LiteralPath $policyKey).GetValue('DisableRealtimeMonitoring', $null)
        if ($null -eq $v) { $prev = '<absent>' } else { $prev = [string]$v }
    }
    if (-not (Test-Path -LiteralPath $stateFile)) { Set-Content -LiteralPath $stateFile -Value $prev -Encoding ASCII }
    if (-not (Test-Path -LiteralPath $policyKey)) { New-Item -Path $policyKey -Force | Out-Null }
    # the policy keeps it off across restarts; Set-MpPreference applies it immediately
    New-ItemProperty -LiteralPath $policyKey -Name 'DisableRealtimeMonitoring' -PropertyType DWord -Value 1 -Force | Out-Null
    Set-MpPreference -DisableRealtimeMonitoring $true
    Write-Output 'LiteOS: Microsoft Defender real-time protection is OFF. Revert this tweak (or delete the policy and turn it on in Windows Security) to protect the PC again.'
}

actions.undo:
$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not (Test-Path -LiteralPath $liteState)) { New-Item -ItemType Directory -Path $liteState -Force | Out-Null }
$policyKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection'
$stateFile = Join-Path $liteState 'prev-defender-rtp-policy.txt'
if (Test-Path -LiteralPath $stateFile) {
    $prev = [string](Get-Content -LiteralPath $stateFile -TotalCount 1)
    if (Test-Path -LiteralPath $policyKey) {
        if ($prev -eq '<absent>' -or $prev -eq '<nokey>') {
            if ($null -ne (Get-Item -LiteralPath $policyKey).GetValue('DisableRealtimeMonitoring', $null)) {
                Remove-ItemProperty -LiteralPath $policyKey -Name 'DisableRealtimeMonitoring'
            }
            $k = Get-Item -LiteralPath $policyKey
            if ($prev -eq '<nokey>' -and $k.ValueCount -eq 0 -and $k.SubKeyCount -eq 0) { Remove-Item -LiteralPath $policyKey -Force }
        } else {
            New-ItemProperty -LiteralPath $policyKey -Name 'DisableRealtimeMonitoring' -PropertyType DWord -Value ([int]$prev) -Force | Out-Null
        }
    }
    Remove-Item -LiteralPath $stateFile -Force
}
try {
    Set-MpPreference -DisableRealtimeMonitoring $false
    Write-Output 'LiteOS: Microsoft Defender real-time protection is ON again.'
} catch {
    Write-Output ('LiteOS: could not switch real-time protection back on automatically (' + $_.Exception.Message + ') - turn it on in Windows Security > Virus & threat protection.')
}
